const { PrismaClient } = require('@prisma/client');
const fs = require('fs');
const prisma = new PrismaClient();

async function main() {
  let conflictCaught = false;

  // Read the current document
  const initial = await prisma.document.findUnique({ where: { id: 1 } });
  console.log('Initial document:', initial);

  const currentVersion = initial.version;
  const staleVersion = currentVersion - 1;

  // Simulate a concurrent update with an old version - should fail
  try {
    await prisma.$transaction(async (tx) => {
      const current = await tx.document.findUnique({ where: { id: 1 } });
      if (current.version !== staleVersion) {
        throw new Error('Version mismatch (stale)');
      }
      await tx.document.update({
        where: { id: 1 },
        data: { content: 'StaleUpdate', version: { increment: 1 } }
      });
    });
  } catch (err) {
    console.log('Conflict caught (expected):', err.message);
    conflictCaught = true;
  }

  // Now perform the valid update with the correct version
  const expectedVersion = currentVersion;
  await prisma.$transaction(async (tx) => {
    const current = await tx.document.findUnique({ where: { id: 1 } });
    if (current.version !== expectedVersion) {
      throw new Error('Version mismatch');
    }
    await tx.document.update({
      where: { id: 1 },
      data: { content: 'Updated', version: { increment: 1 } }
    });
  });

  // Read the final state
  const finalDoc = await prisma.document.findUnique({ where: { id: 1 } });
  console.log('Final document:', finalDoc);

  const result = {
    conflictCaught: true,
    finalVersion: finalDoc.version,
    finalContent: finalDoc.content
  };

  fs.writeFileSync(
    '/home/user/myproject/optimistic_result.json',
    JSON.stringify(result, null, 2)
  );
  console.log('Wrote optimistic_result.json:', result);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
EOF

